-- Dominio do salao, ticket 06: rodadas (a batch of items sent together) and the items of a comanda (tenant tables, exact RLS, composite FKs).
--   rodadas        id is generated by the CLIENT (UUID v7): sending the same id again is a repeat, never a second round. enviada_por is the waiter who sent it (only they may undo it, inside
--                  the undo window). comanda_versao is the comanda version this round produced, so a repeat answers with the very same response. desfeita_em is set when the whole round is undone.
--   itens_comanda  product name and price are COPIED at launch (a later product change never reaches the bill). quantidade is a positive integer. A cancelled item keeps its row, the reason and
--                  who cancelled it; it leaves the consumption.
CREATE TABLE rodadas (
  id             uuid PRIMARY KEY,
  organizacao_id uuid        NOT NULL REFERENCES organizacoes (id),
  unidade_id     uuid        NOT NULL,
  comanda_id     uuid        NOT NULL,
  enviada_por    uuid        NOT NULL,
  enviada_em     timestamptz NOT NULL,
  desfeita_em    timestamptz,
  comanda_versao integer     NOT NULL CHECK (comanda_versao >= 2),
  UNIQUE (organizacao_id, id),
  FOREIGN KEY (organizacao_id, unidade_id) REFERENCES unidades (organizacao_id, id),
  FOREIGN KEY (organizacao_id, comanda_id) REFERENCES comandas (organizacao_id, id),
  FOREIGN KEY (organizacao_id, enviada_por) REFERENCES contas (organizacao_id, id)
);

CREATE INDEX rodadas_por_comanda ON rodadas (organizacao_id, comanda_id, enviada_em);

CREATE TABLE itens_comanda (
  id                   uuid PRIMARY KEY,
  organizacao_id       uuid        NOT NULL REFERENCES organizacoes (id),
  comanda_id           uuid        NOT NULL,
  rodada_id            uuid        NOT NULL,
  posicao              integer     NOT NULL CHECK (posicao >= 1),
  produto_id           uuid        NOT NULL,
  produto_nome         text        NOT NULL CHECK (length(produto_nome) BETWEEN 1 AND 120),
  preco_centavos       bigint      NOT NULL CHECK (preco_centavos >= 0),
  quantidade           integer     NOT NULL CHECK (quantidade >= 1),
  observacao           text        CHECK (length(observacao) BETWEEN 1 AND 200),
  estado               text        NOT NULL DEFAULT 'lancado' CHECK (estado IN ('lancado', 'cancelado')),
  motivo_cancelamento  text        CHECK (length(motivo_cancelamento) BETWEEN 1 AND 200),
  cancelado_por        uuid,
  cancelado_em         timestamptz,
  UNIQUE (organizacao_id, id),
  UNIQUE (organizacao_id, rodada_id, posicao),
  FOREIGN KEY (organizacao_id, comanda_id) REFERENCES comandas (organizacao_id, id),
  FOREIGN KEY (organizacao_id, rodada_id) REFERENCES rodadas (organizacao_id, id),
  FOREIGN KEY (organizacao_id, produto_id) REFERENCES produtos (organizacao_id, id),
  FOREIGN KEY (organizacao_id, cancelado_por) REFERENCES contas (organizacao_id, id),
  CHECK ((estado = 'cancelado') = (motivo_cancelamento IS NOT NULL AND cancelado_por IS NOT NULL AND cancelado_em IS NOT NULL))
);

CREATE INDEX itens_comanda_por_comanda ON itens_comanda (organizacao_id, comanda_id);

ALTER TABLE rodadas ENABLE ROW LEVEL SECURITY;
ALTER TABLE rodadas FORCE  ROW LEVEL SECURITY;
CREATE POLICY isolamento ON rodadas
  USING (organizacao_id = (SELECT app_organizacao_id()))
  WITH CHECK (organizacao_id = (SELECT app_organizacao_id()));

ALTER TABLE itens_comanda ENABLE ROW LEVEL SECURITY;
ALTER TABLE itens_comanda FORCE  ROW LEVEL SECURITY;
CREATE POLICY isolamento ON itens_comanda
  USING (organizacao_id = (SELECT app_organizacao_id()))
  WITH CHECK (organizacao_id = (SELECT app_organizacao_id()));
